function [e] = ephem_inputs(jd_tdb, rs, vs, rm, vm)
%EPHEM_INPUTS  ephemInputs(jdTDB): the force stack's one ephemeris interface, from the geocentric Sun and Moon [m, m/s].
%   jd_tdb: real[1] (passed a plain number)
%   rs: real[1][3] (passed a plain number)
%   vs: real[1][3] (passed a plain number)
%   rm: real[1][3] (passed a plain number)
%   vm: real[1][3] (passed a plain number)
%   returns e: EphemOut (passed rec)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    e = asils.models.de440.EphemOut_zero();
    k = asils.models.de440.de440_constants();
    e = asils.models.de440.EphemOut_zero();
    d = asils.pc.norm_(rs);
    q = (k.au_m / d);
    e.jd_tdb = jd_tdb;
    e.sun_unit = (rs / d);
    e.sun_dist = d;
    e.flux_scale = (q * q);
    e.p_srp = (k.p0 * e.flux_scale);
    e.sun_eci = rs;
    e.sun_vel = vs;
    e.moon_eci = rm;
    e.moon_vel = vm;
    e.gm_sun = k.gm_sun;
    e.gm_moon = k.gm_moon;
    e.earth_helio_pos = (-(rs));
    e.earth_helio_vel = (-(vs));
    e.sun_ra = atan2(rs(2), rs(1));
    e.sun_dec = asils.pc.asin_((rs(3) / d));
end
